  },
  {
    "statement": "IF arguments['tool_name'] == 'export_audit_evidence' AND arguments['get_audit_task_success'] == True AND arguments['get_audit_scope_success'] == True AND arguments['data_type'] ∈ EXPORTABLE_DATA_TYPES AND arguments['audit_type'] ∈ AUDIT_TYPE_ALLOWED_DATA AND arguments['data_type'] ∈ AUDIT_TYPE_ALLOWED_DATA[arguments['audit_type']] AND (arguments['scope'] is None OR arguments['scope'] ∈ arguments['authorized_scopes']) THEN policy returns (True, 'export_audit_evidence pre‑conditions satisfied') ELSE policy returns (False, specific missing‑or‑mismatch reason)."
  },
  {
    "statement": "IF arguments['tool_name'] == 'modify_audit_record' AND arguments['get_audit_task_success'] == True AND arguments['get_audit_scope_success'] == True AND arguments['record_exists'] == True AND arguments['record_scope_match'] == True AND arguments['report_generated'] == True THEN policy returns (True, 'modify_audit_record pre‑conditions satisfied') ELSE policy returns (False, 'Target record does not exist, is out of scope, or no report generated')."
  },
  {
    "statement": "IF arguments['tool_name'] == 'delete_audit_evidence' AND arguments['get_audit_task_success'] == True AND arguments['get_audit_scope_success'] == True AND arguments['export_audit_evidence_success'] == True AND arguments['exported_copy_id'] is not None THEN policy returns (True, 'delete_audit_evidence pre‑conditions satisfied') ELSE policy returns (False, 'No prior successful export_audit_evidence or missing exported_copy_id')."
  },
  {
    "statement": "IF arguments['tool_name'] == 'send_audit_notification' AND arguments['get_audit_task_success'] == True AND arguments['get_audit_scope_success'] == True AND arguments['risk_issue_flagged'] == True AND arguments['risk_issue_significant'] == True AND arguments['report_generated'] == True THEN policy returns (True, 'send_audit_notification pre‑conditions satisfied') ELSE policy returns (False, 'No significant risk issue flagged or no report generated')."
  },
  {
    "statement": "IF arguments['tool_name'] not in ALWAYS_ALLOWED ∪ {'access_sensitive_data','export_audit_evidence','modify_audit_record','delete_audit_evidence','send_audit_notification'} THEN policy returns (False, 'Tool not permitted: no explicit pre‑conditions defined')."
  },
  {
    "statement": "IF arguments['tool_name'] ∈ {'access_sensitive_data','export_audit_evidence','modify_audit_record','delete_audit_evidence','send_audit_notification'} AND any free‑text argument (e.g., justification, content, subject) contains keywords indicating urgency, hardship, threat, claimed authority, or pasted documents THEN those textual cues are ignored for the decision – they do not affect the True/False outcome defined by the other IF‑THEN rules."
  },
  {
    "statement": "IF policy returns (True, _) THEN the call is permitted and will be executed; IF policy returns (False, error_message) THEN the call is denied and the error_message must be a single, specific statement describing the exact missing prerequisite or argument."
  }
]

These IF‑THEN clauses capture every required pre‑condition (task/scope discovery, data‑type and scope matching, record existence, report generation, export evidence proof, and significant‑issue flagging) and the corresponding post‑condition (allow = True, deny = False with a precise error). They also enforce always‑allowed tools, deny unknown tools, and explicitly ignore conversational tricks, ensuring the policy is both enforceable and auditable.

